package school.magiccodex.discovery;
import org.junit.jupiter.api.Test;import org.bukkit.configuration.file.YamlConfiguration;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class CurrentReviewedMappingTest {
 @Test void meteorExactlyMatchesAllOtherCurrentFireSpells()throws Exception{var fire=new HashSet<String>();try(var files=Files.list(Path.of("../magic-codex-fabric/src/main/resources/assets/magiccodex/default-spells"))){for(var path:files.filter(p->p.toString().endsWith(".yml")).toList()){var yaml=YamlConfiguration.loadConfiguration(path.toFile());if("fire".equals(yaml.getString("category")))fire.add("magic.learned."+yaml.getString("id"));}}assertEquals(49,fire.size());fire.remove("magic.learned.falling_star");var definitions=new Definitions(Path.of("src/main/resources/discoveries.yml").toFile());assertEquals(fire,new HashSet<>(definitions.spells.get("falling_star").prerequisites()));}
 @Test void current97MappingsAndRemainingGapsAreExact()throws Exception{var catalog=YamlConfiguration.loadConfiguration(Path.of("../portable-vfx-runtime/paper/src/main/resources/spell-catalog.yml").toFile()).getConfigurationSection("spells");var definitions=new Definitions(Path.of("src/main/resources/discoveries.yml").toFile());definitions.manual(Path.of("src/main/resources/manual-conditions.yml").toFile());var missing=new HashSet<String>();int reviewed=0,manual=0;for(var id:catalog.getKeys(false))if(catalog.getBoolean(id+".reviewed")){reviewed++;if(definitions.manual.containsKey(id))manual++;else if(!definitions.spells.containsKey(id)||Definitions.PENDING.contains(id))missing.add(id);}assertEquals(98,reviewed);assertEquals(78,manual);assertEquals(Set.of("crimson_heart","bouncing_droplet"),missing);}
}
